{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeat testing is undocumented; its absence cannot be inferred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score supplies no evidence of consistency across runs."
        }
      ],
      "instrument_review": "EFPA 9.3 and 9.7 apply by interpreting repeated AI evaluations as replications of testing procedures. Repeatability evidence is insufficient, corresponding to 0 rather than 1 where rated. This does not establish poor reliability."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated evaluations."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "ran the evaluation exactly once",
          "reason": "No repeated scores establish stability or instability."
        }
      ],
      "instrument_review": "Under EFPA 9.3 and 9.7, repeated AI runs are a reinterpretation of replication studies. Their explicit absence leaves repeatability unassessed; it does not demonstrate inadequate consistency. EFPA 9.8 requires evidence appropriate to the intended comparison."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated evaluations held the specified conditions constant and reported score variation."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability threshold of at most two percentage points."
        }
      ],
      "instrument_review": "EFPA 9.7 accommodates the reported range as alternative precision evidence from repeated AI runs, related to 9.3 replication. It supports the stated local stability definition. It is not a reliability coefficient and does not justify an automatic EFPA excellence rating or wider generalisation."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "The developers examined repeated scores under the same specified conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the report's stability threshold of at most two percentage points."
        }
      ],
      "instrument_review": "EFPA 9.7 treats repeated AI runs and their score range as alternative precision evidence. Unlike missing evidence, these results demonstrate failure of the stated stability criterion. Under 9.8, this directly concerns the intended performance comparison, without supplying a conventional reliability coefficient."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not document repeated evaluations."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added documentation supplies no evidence about score consistency."
        }
      ],
      "instrument_review": "EFPA 6.3.8 concerns software instructions and support; those materials are distinct from reliability evidence under 9.3 and 9.7. Download and dependency instructions cannot establish repeatability or software robustness. Repeatability remains insufficiently documented, rather than demonstrated inadequate."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "The reported exact-grid results show better observed performance by A on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "These results provide insufficient evidence for intelligence across domains."
        }
      ],
      "instrument_review": "EFPA 3.2 supports describing the observed scores. Sections 6.1, 10.1 and 10.5 require validity to be judged against the intended interpretation, here limited to evaluated grid puzzles. The narrow comparison is supported; cross-domain intelligence is an unsupported extension, not a disproven capability."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A achieved the higher observed score on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "Stating a broad intended use does not supply evidence supporting that inference."
        }
      ],
      "instrument_review": "EFPA 6.1 and 10.1 raise the match between the claimed construct and sampled content; 10.3 and 10.5 require evidence supporting the intended cross-domain selection. The supplied evidence establishes a narrow score difference but leaves the broad interpretation unestablished. Critical validity evidence is insufficient, not proof that A lacks greater intelligence."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "Scores alone provide no reported comparative evidence of improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomised trial supports greater correctness with A in the studied setting; the reported difference interval is positive."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "An improvement in correctness does not establish an unmeasured safety benefit."
        }
      ],
      "instrument_review": "EFPA 10.3.1.6 addresses experimental evidence, and 10.3.2 addresses relations to relevant outcome criteria. Random allocation, new cases, blinded correctness checks and reported uncertainty support the stated workshop use. The 120 inspectors are trial participants, not an AI norm sample. Correctness percentages are outcome measures, not reliability coefficients or AUC values. Transfer elsewhere and safety benefits remain unestablished."
    }
  ],
  "closing_note": "No task clarification was needed. The original EFPA model was retained, with selective discussion as requested rather than full forms or an aggregate score. AI systems replace human test takers only where explicitly reinterpreted; literal human sensory, motor and debriefing questions are inapplicable to the AI itself, while requirements concerning human users or trial participants may remain relevant. Unreported norms, adaptations, materials, fairness analyses and generated reports cannot be assumed absent or inapplicable. Labels classify the probes, not EFPA quality. Missing critical evidence limits justified use under EFPA guidance without proving poor quality. Apparent extraction inconsistencies were not resolved using outside material. Source: EFPA Test Review Model 2025, supplied extraction, CC BY-SA 4.0; https://www.efpa.eu/."
}
